    // ---- Schedule for cov_sum (M x M reductions over N samples) ----
    //
    // This is the main O(M^2 * N) kernel. We want good data reuse and
    // parallel execution:
    //  - tile the (i,j) covariance matrix into tile_cov x tile_cov blocks
    //  - parallelize across outer tiles in j
    //  - keep the reduction variable innermost over tiles
    //  - vectorize across i inside each tile (contiguous dimension)
    {
        Var io("io"), jo("jo"), ii("ii"), jj("jj");

        cov_sum.compute_root();

        cov_sum.update()
            .split(i, io, ii, tile_cov)
            .split(j, jo, jj, tile_cov)
            // Order (from innermost to outermost) for this update:
            //   ii (vectorized columns within tile)
            //   jj (rows within tile)
            //   r_samples (reduction over samples)
            //   io (tile index along i)
            //   jo (tile index along j, parallelized)
            .reorder(ii, jj, r_samples, io, jo)
            .parallel(jo)
            .vectorize(ii, vec);
    }

    // ---- Schedule for covariance (final normalization) ----
    //
    // Cheap pointwise stage: parallelize across rows of the matrix and
    // vectorize across columns.
    {
        covariance
            .compute_root()
            .parallel(j)
            .vectorize(i, vec);
    }

    // -----------------------------
    // Bind runtime parameters
    // -----------------------------

    data_param.set(data);
    float_n_param.set(float_n);

    // JIT-compile the final stage with the chosen target.
    covariance.compile_jit(target);

    // -----------------------------
    // Run and time the kernel
    // -----------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the covariance matrix into 'cov'.
    covariance.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

