    //   - float  (4 bytes)  -> 8 lanes
    //   - double (8 bytes)  -> 4 lanes
    //   - 2‑byte types      -> 16 lanes
    constexpr int vector_width =
        (sizeof(num_t) == 8) ? 4 :
        (sizeof(num_t) == 4) ? 8 :
